def hidden_rule_fn(state):
    grid_size = 8

    def toroidal_delta(a, b):
        """Compute signed toroidal delta from a to b."""
        dx = (b - a) % grid_size
        if dx > grid_size // 2:
            dx -= grid_size
        return dx

    def chromodistance(p, q):
        """Chromodistance on 8x8 toroidal grid with type mismatch penalty."""
        dx = abs(toroidal_delta(p['x'], q['x']))
        dy = abs(toroidal_delta(p['y'], q['y']))
        dist = max(dx, dy)
        if p['type'] != q['type']:
            dist += 1
        return dist

    def lex_smaller(a, b):
        """Return the lexicographically smaller (x, y) tuple."""
        if (a['x'], a['y']) <= (b['x'], b['y']):
            return a
        return b

    def find_nearest_partner(particles, p, same_type=True):
        """Find the nearest other particle of appropriate type."""
        candidates = [q for q in particles if q is not p]
        if same_type:
            candidates = [q for q in candidates if q['type'] == p['type']]
        else:
            # For GLORP, find nearest ZEX
            candidates = [q for q in candidates if q['type'] == 'ZEX']

        if not candidates:
            return None

        best = None
        best_dist = float('inf')
        for c in candidates:
            d = chromodistance(p, c)
            if d < best_dist:
                best_dist = d
                best = c
            elif d == best_dist:
                best = lex_smaller(best, c)
        return best

    def move_toward(current, target):
        """Move one step toward target along axis with largest signed toroidal delta."""
        dx = toroidal_delta(current['x'], target['x'])
        dy = toroidal_delta(current['y'], target['y'])

        new_x = current['x']
        new_y = current['y']

        if abs(dx) > abs(dy):
            new_x = (current['x'] + dx // abs(dx) if dx != 0 else current['x']) % grid_size
        elif abs(dy) > abs(dx):
            new_y = (current['y'] + dy // abs(dy) if dy != 0 else current['y']) % grid_size
        else:
            # Tie: x preferred
            if dx != 0:
                new_x = (current['x'] + dx // abs(dx)) % grid_size

        return {'type': current['type'], 'x': new_x, 'y': new_y}

    def move_away(current, target):
        """Move one step away from target along axis with largest signed toroidal delta."""
        dx = toroidal_delta(current['x'], target['x'])
        dy = toroidal_delta(current['y'], target['y'])

        new_x = current['x']
        new_y = current['y']

        if abs(dx) > abs(dy):
            new_x = (current['x'] - dx // abs(dx) if dx != 0 else current['x']) % grid_size
        elif abs(dy) > abs(dx):
            new_y = (current['y'] - dy // abs(dy) if dy != 0 else current['y']) % grid_size
        else:
            # Tie: x preferred
            if dx != 0:
                new_x = (current['x'] - dx // abs(dx)) % grid_size

        return {'type': current['type'], 'x': new_x, 'y': new_y}

    next_state = []
    for i, particle in enumerate(state):
        if particle['type'] == 'ZEX':
            nearest = find_nearest_partner(state, particle, same_type=True)
            if nearest:
                next_state.append(move_toward(particle, nearest))
            else:
                next_state.append({'type': particle['type'], 'x': particle['x'], 'y': particle['y']})
        else:  # GLORP
            nearest = find_nearest_partner(state, particle, same_type=False)
            if nearest:
                next_state.append(move_away(particle, nearest))
            else:
                next_state.append({'type': particle['type'], 'x': particle['x'], 'y': particle['y']})

    return next_state
